363	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
364	func (l *ledgerFile) validate() error {
365		for id, p := range l.Parcels {
366			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
367				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
368			}
369			switch p.Status {
370			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
371			default:
372				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
373			}
374			for i, e := range p.Trail {
375				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
376					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
377				}
378				if e.Op == "退回" {
379					if e.Request == "" || e.Reason == "" || e.From == "" {
380						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
381					}
382					if _, ok := l.Handoffs[e.RefRequest]; !ok {
383						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
384					}
385				}
386				if e.Op == "出站" {
387					if e.Batch == "" || e.Courier == "" {
388						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
389					}
390					if _, ok := l.Batches[e.Batch]; !ok {
391						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
392					}
393				}
394				if e.Op == "回执" {
395					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
396						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
397					}
398					if e.Result == resultFailed && e.Reason == "" {
399						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
400					}
401					if _, ok := l.Batches[e.Batch]; !ok {
402						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
403					}
404				}
405				if e.Op == "撤销回执" {
406					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
407						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
408					}
409					b, ok := l.Batches[e.Batch]
410					if !ok || b == nil {
411						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
412					}
413					if e.Station != b.Station {
414						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
415							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
416					}
417					rv, ok := l.Revokes[e.Request]
418					if !ok || rv == nil {
419						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
420					}
421					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
422						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
423					}
424				}
425				if e.Op == "收回" {
426					if e.Batch == "" || e.Request == "" || e.Reason == "" {
427						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
428					}
429					a, ok := l.Aborts[e.Request]
430					if !ok || a == nil {
431						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
432					}
433					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
434						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
435					}
436					inAbort := false
437					for _, pid := range a.Parcels {
438						if pid == id {
439							inAbort = true
440							break
441						}
442					}
443					if !inAbort {
444						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
445					}
446				}
447				if e.Op == "续接" {
448					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
449						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
450					}
451					t, ok := l.Transfers[e.Request]
452					if !ok || t == nil {
453						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
454					}
455					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
456						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
457						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
458					}
459					inTransfer := false
460					for _, pid := range t.Parcels {
461						if pid == id {
462							inTransfer = true
463							break
464						}
465					}
466					if !inTransfer {
467						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
468					}
469				}
470				if e.Op == "发运" {
471					if e.Shipment == "" || e.From == "" || e.To == "" {
472						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹缺少运输单号、源站或目的站", ErrCorrupt, id, i+1)
473					}
474					sh, ok := l.Shipments[e.Shipment]
475					if !ok || sh == nil {
476						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
477					}
478					if sh.From != e.From || sh.To != e.To || e.Station != e.From || !sh.Time.Equal(e.Time) {
479						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹与运输单 %q 记录不一致", ErrCorrupt, id, i+1, e.Shipment)
480					}
481					inShipment := false
482					for _, pid := range sh.Parcels {
483						if pid == id {
484							inShipment = true
485							break
486						}
487					}
488					if !inShipment {
489						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹不在运输单 %q 的成员集合中", ErrCorrupt, id, i+1, e.Shipment)
490					}
491				}
492				if e.Op == "接收" {
493					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" {
494						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹缺少运输单号、接收请求号、源站或目的站", ErrCorrupt, id, i+1)
495					}
496					rv, ok := l.Receives[e.Request]
497					if !ok || rv == nil {
498						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的接收请求 %q", ErrCorrupt, id, i+1, e.Request)
499					}
500					if rv.Shipment != e.Shipment || rv.Station != e.Station || e.Station != e.To || !rv.Time.Equal(e.Time) {
501						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹与接收请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
502					}
503					sh, ok := l.Shipments[e.Shipment]
504					if !ok || sh == nil {
505						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
506					}
507					if sh.From != e.From {
508						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的源站与运输单 %q 记录（源站 %q）不一致",
509							ErrCorrupt, id, i+1, e.Shipment, sh.From)
510					}
511					// 接收目的站必须等于受理时的有效目的站（应用该件此前各次改址后），
512					// 由下方按保存顺序的生命周期校验核对。
513					inReceive := false
514					for _, pid := range rv.Parcels {
515						if pid == id {
516							inReceive = true
517							break
518						}
519					}
520					if !inReceive {
521						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹不在接收请求 %q 的成员集合中", ErrCorrupt, id, i+1, e.Request)
522					}
523				}
524				if e.Op == "改址" {
525					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" || e.Reason == "" {
526						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹缺少运输单号、改址请求号、前后目的站或原因", ErrCorrupt, id, i+1)
527					}
528					r, ok := l.Reroutes[e.Request]
529					if !ok || r == nil {
530						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹引用了不存在的改址请求 %q", ErrCorrupt, id, i+1, e.Request)
531					}
532					if r.Shipment != e.Shipment || r.From != e.From || r.To != e.To || r.Reason != e.Reason || !r.Time.Equal(e.Time) {
533						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹与改址请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
534					}
535					inReroute := false
536					for _, pid := range r.Parcels {
537						if pid == id {
538							inReroute = true
539							break
540						}
541					}
542					if !inReroute {
543						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹不在改址请求 %q 的集合中", ErrCorrupt, id, i+1, e.Request)
544					}
545				}
546				if e.Op == "冻结" {
547					if e.Incident == "" || e.Reason == "" {
548						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
549					}
550					f, ok := l.Freezes[e.Incident]
551					if !ok || f == nil {
552						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
553					}
554					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
555						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
556					}
557				}
558				if e.Op == "解除冻结" {
559					if e.Incident == "" || e.Request == "" || e.Note == "" {
560						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
561					}
562					f, ok := l.Freezes[e.Incident]
563					if !ok || f == nil {
564						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
565					}
566					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
567						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
568					}
569					u, ok := l.Unfreezes[e.Request]
570					if !ok || u == nil || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
571						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
572					}
573				}
574			}
575		}
576		// 站间运输生命周期：按每件轨迹的保存顺序（不按发生时间排序）核对发运、改址与
577		// 接收的配对关系。每张运输单的成员恰有一次对应发运；已接收时恰有一次对应接收
578		// 且位于发运之后；发运后到接收前除改址外不得出现其他作业轨迹；改址记录必须
579		// 按运输单改址列表的保存顺序逐一对应，且接收目的站等于应用此前各次改址后的
580		// 有效目的站；未接收时不得有接收记录，发运（及其后的改址）必须是最后的轨迹。
581		for id, p := range l.Parcels {
582			shipped := make(map[string]bool) // 该包裹轨迹中已出现发运的运输单号
583			var open string                  // 已发运、尚未在轨迹中接收的在途运输单号
584			rerouteIdx := 0                  // 当前在途运输单已在轨迹中出现的改址次数（按运输单改址列表顺序）
585			for i, e := range p.Trail {
586				if open != "" && e.Op != "接收" && e.Op != "改址" {
587					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹（%s）出现在运输单 %q 发运之后、接收之前，在途期间不得有其他作业轨迹",
588						ErrCorrupt, id, i+1, e.Op, open)
589				}
590				switch e.Op {
591				case "发运":
592					if shipped[e.Shipment] {
593						return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹重复发运运输单 %q，每张运输单的成员恰有一次对应发运",
594							ErrCorrupt, id, i+1, e.Shipment)
595					}
596					shipped[e.Shipment] = true
597					open = e.Shipment
598					rerouteIdx = 0
599				case "改址":
600					if open == "" {
601						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹（运输单 %q）位于对应发运之前或接收之后，在途期间才能改址",
602							ErrCorrupt, id, i+1, e.Shipment)
603					}
604					if e.Shipment != open {
605						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
606							ErrCorrupt, id, i+1, e.Shipment, open)
607					}
608					sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
609					if e.Station != sh.From {
610						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹的站点 %q 与运输单 %q 源站 %q 不一致，改址不移动包裹",
611							ErrCorrupt, id, i+1, e.Station, open, sh.From)
612					}
613					if rerouteIdx >= len(sh.Reroutes) || sh.Reroutes[rerouteIdx] != e.Request {
614						return fmt.Errorf("%w: 包裹 %q 第 %d 条改址轨迹（改址请求 %q）与运输单 %q 按保存顺序的改址列表不一致",
615							ErrCorrupt, id, i+1, e.Request, open)
616					}
617					rerouteIdx++
618				case "接收":
619					if open == "" {
620						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹（运输单 %q）位于对应发运之前或缺少对应发运",
621							ErrCorrupt, id, i+1, e.Shipment)
622					}
623					if e.Shipment != open {
624						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
625							ErrCorrupt, id, i+1, e.Shipment, open)
626					}
627					// 接收目的站必须等于受理时的有效目的站：原目的站按保存顺序应用
628					// 该件接收前已发生的各次改址（轨迹中前 rerouteIdx 次）。
629					sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
630					eff := sh.To
631					for j := 0; j < rerouteIdx; j++ {
632						eff = l.Reroutes[sh.Reroutes[j]].To // 改址轨迹校验已保证请求存在且非空
633					}
634					if e.To != eff {
635						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的目的站 %q 与运输单 %q 当时有效目的站 %q 不一致",
636							ErrCorrupt, id, i+1, e.To, open, eff)
637					}
638					open = ""
639				}
640			}
641			if open != "" {
642				sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
643				if sh.ReceivedBy != "" {
644					return fmt.Errorf("%w: 包裹 %q 的运输单 %q 已接收（接收请求号 %q），但轨迹缺少对应的接收记录",
645						ErrCorrupt, id, open, sh.ReceivedBy)
646				}
647				// 未收件属于每次改址的集合：轨迹中的改址记录必须覆盖该单全部改址。
648				if rerouteIdx != len(sh.Reroutes) {
649					return fmt.Errorf("%w: 包裹 %q 尚未接收，但缺少运输单 %q 的改址轨迹（轨迹 %d 次，改址列表 %d 次），未收件属于每次改址集合",
650						ErrCorrupt, id, open, rerouteIdx, len(sh.Reroutes))
651				}
652			}
653		}
654		// 当前归属与状态必须由轨迹记录形成：按保存顺序的最后一条轨迹推导应有的归属
655		// 站点与状态，与台账当前值不一致即存在无对应记录的站点或状态改变。接收后的
656		// 合法后续流转（交接、再次发运、回执及其撤销、收回、续接、冻结与解除）会
657		// 产生新的末条轨迹，按新轨迹校验，不因历史接收而把成员固定在目的站。
658		for id, p := range l.Parcels {
659			last := p.Trail[len(p.Trail)-1]
660			var want string
661			switch last.Op {
662			case "收件", "交接", "退回", "收回", "接收", "解除冻结":
663				want = statusInStation
664			case "出站", "续接", "撤销回执":
665				want = statusDelivering
666			case "回执":
667				if last.Result == resultSigned {
668					want = statusSigned
669				} else {
670					want = statusInStation
671				}
672			case "冻结":
673				want = statusFrozen
674			case "发运", "改址":
675				want = statusInTransit // 改址不移动包裹：仍归源站、保持站间在途
676			default:
677				continue // 未知操作不参与推导（逐条校验已兜底）
678			}
679			if p.Station != last.Station || p.Status != want {
680				return fmt.Errorf("%w: 包裹 %q 当前归属 %q、状态 %q 与最后一条轨迹（%s，站点 %q）应形成的归属与状态 %q、%q 不一致",
681					ErrCorrupt, id, p.Station, p.Status, last.Op, last.Station, last.Station, want)
682			}
683		}
684		for req, h := range l.Handoffs {
685			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
686				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
687			}
688			for _, id := range h.Parcels {
689				if _, ok := l.Parcels[id]; !ok {
690					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
691				}
692			}
693			if h.ReturnedBy != "" {
694				r, ok := l.Returns[h.ReturnedBy]
695				if !ok || r == nil || r.Handoff != req {
696					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
697				}
698			}
699		}
700		for req, r := range l.Returns {
701			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
702				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
703				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
704			}
705			h, ok := l.Handoffs[r.Handoff]
706			if !ok || h == nil {
707				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
708			}
709			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
710				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
711			}
712			for _, id := range r.Parcels {
713				if _, ok := l.Parcels[id]; !ok {
714					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
715				}
716			}
717		}
718		for id, b := range l.Batches {
719			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
720				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
721			}
722			seen := make(map[string]bool, len(b.Parcels))
723			for _, pid := range b.Parcels {
724				if seen[pid] {
725					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
726				}
727				seen[pid] = true
728				if _, ok := l.Parcels[pid]; !ok {
729					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
730				}
731			}
732			for pid, e := range b.Receipts {
733				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
734					(e.Result != resultSigned && e.Result != resultFailed) ||
735					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
736					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
737				}
738				rc, ok := l.Receipts[e.Request]
739				if !ok || rc == nil || rc.Batch != id || rc.Parcel != pid {
740					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
741				}
742				if e.RevokedBy != rc.RevokedBy {
743					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
744				}
745			}
746			if b.AbortedBy != "" {
747				a, ok := l.Aborts[b.AbortedBy]
748				if !ok || a == nil || a.Batch != id {
749					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
750				}
751			}
752			if b.TransferredBy != "" {
753				if b.AbortedBy != "" {
754					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
755				}
756				t, ok := l.Transfers[b.TransferredBy]
757				if !ok || t == nil || t.FromBatch != id {
758					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
759				}
760			}
761			if b.RelayedFrom != "" {
762				t, ok := l.Transfers[b.RelayRequest]
763				if !ok || t == nil || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
764					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
765						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
