769			}
770		}
771		for req, rc := range l.Receipts {
772			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
773				(rc.Result != resultSigned && rc.Result != resultFailed) ||
774				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
775				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
776			}
777			b, ok := l.Batches[rc.Batch]
778			if !ok || b == nil {
779				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
780			}
781			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
782			// 因此该件在批次内必须始终有一条回执条目。
783			e, cur := b.Receipts[rc.Parcel]
784			if !cur {
785				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
786			}
787			if rc.RevokedBy == "" {
