789				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
790					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
791				}
792				continue
793			}
794			// 已撤销回执：撤销关联必须存在且回指该回执。
795			rv, ok := l.Revokes[rc.RevokedBy]
796			if !ok || rv == nil || rv.Receipt != req {
797				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
798			}
799			if e.Request == req {
800				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
801				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
802					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
803				}
804			}
805			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
806		}
807		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
808		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
809		for req, rv := range l.Revokes {
810			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
811				rv.Reason == "" || rv.Time.IsZero() {
812				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
813			}
814			rc, ok := l.Receipts[rv.Receipt]
815			if !ok || rc == nil {
816				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
817			}
818			if rc.RevokedBy != req {
819				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
820			}
821			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
822				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
823			}
824			p, ok := l.Parcels[rv.Parcel]
825			if !ok {
826				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
827			}
828			found := false
829			for _, e := range p.Trail {
830				if e.Op == "撤销回执" && e.Request == req {
831					found = true
832					break
833				}
834			}
835			if !found {
836				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
837			}
838		}
839		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序，已撤销回执不计入
840		// 有效回执），且每件收回包裹的轨迹中都有与该中止请求一致的收回记录；
841		// 中止记录与收回轨迹不一致即损坏。
842		for req, a := range l.Aborts {
843			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
844				len(a.Parcels) == 0 || a.Time.IsZero() {
845				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
846			}
847			b, ok := l.Batches[a.Batch]
848			if !ok || b == nil {
849				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
850			}
851			if b.AbortedBy != req {
852				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
853			}
854			if a.Station != b.Station {
855				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
856			}
857			expect := make([]string, 0, len(b.Parcels))
858			for _, pid := range b.Parcels {
859				if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
860					expect = append(expect, pid)
861				}
862			}
863			if len(expect) != len(a.Parcels) {
864				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
865			}
866			for i := range expect {
867				if expect[i] != a.Parcels[i] {
868					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
869				}
870			}
871			for _, pid := range a.Parcels {
872				p, ok := l.Parcels[pid]
873				if !ok {
874					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
875				}
876				found := false
877				for _, e := range p.Trail {
878					if e.Op == "收回" && e.Request == req {
879						found = true
880						break
881					}
882				}
883				if !found {
884					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
885				}
886			}
887		}
888		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
889		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
890		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
891		for req, t := range l.Transfers {
892			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
893				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
894				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
895				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
896			}
897			fb, ok := l.Batches[t.FromBatch]
898			if !ok || fb == nil {
899				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
900			}
901			if fb.TransferredBy != req {
902				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
903			}
904			if fb.Station != t.Station || fb.Courier != t.FromCourier {
905				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
906			}
907			nb, ok := l.Batches[t.ToBatch]
908			if !ok || nb == nil {
909				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
910			}
911			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
912				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
913			}
914			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
915				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
916			}
917			expect := make([]string, 0, len(fb.Parcels))
918			for _, pid := range fb.Parcels {
919				if e, done := fb.Receipts[pid]; !done || e.RevokedBy != "" {
920					expect = append(expect, pid)
921				}
922			}
923			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
924				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
925					ErrCorrupt, req, t.FromBatch, t.ToBatch)
926			}
927			for _, pid := range t.Parcels {
928				p, ok := l.Parcels[pid]
929				if !ok {
930					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
931				}
932				found := false
933				for _, e := range p.Trail {
934					if e.Op == "续接" && e.Request == req {
935						found = true
936						break
937					}
938				}
939				if !found {
940					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
941				}
942			}
943		}
944		// 发运：成员必须非空、不重复且都已登记，每件成员的轨迹中都有与该运输单一致的
945		// 发运记录；尚未接收的成员必须仍归该单在途（状态为站间在途、归属源站），已接收
946		// 成员的现状不限（其后续流转不影响接收事实）；一件包裹同时只能属于一张运输单的
947		// 未接收成员。全部接收标记必须与各次接收事实一致：全部成员均已接收时恰有
948		// 完成接收的请求号，未全部接收时不得标记。关联缺失或矛盾即损坏。
949		receivedByShipment := make(map[string]map[string]bool) // 运输单号 -> 已接收成员集合
950		for _, r := range l.Receives {
951			if r == nil {
952				continue // 空关联由接收结果校验统一报错
953			}
954			set := receivedByShipment[r.Shipment]
955			if set == nil {
956				set = make(map[string]bool)
957				receivedByShipment[r.Shipment] = set
958			}
959			for _, pid := range r.Parcels {
960				set[pid] = true
961			}
962		}
