964		for no, sh := range l.Shipments {
965			if sh == nil || no != sh.Shipment || sh.From == "" || sh.To == "" || sh.From == sh.To ||
966				len(sh.Parcels) == 0 || sh.Time.IsZero() {
967				return fmt.Errorf("%w: 运输单号 %q 的发运结果不完整", ErrCorrupt, no)
968			}
969			seen := make(map[string]bool, len(sh.Parcels))
970			for _, pid := range sh.Parcels {
971				if seen[pid] {
972					return fmt.Errorf("%w: 运输单 %q 的成员 %q 重复", ErrCorrupt, no, pid)
973				}
974				seen[pid] = true
975				p, ok := l.Parcels[pid]
976				if !ok {
977					return fmt.Errorf("%w: 运输单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, pid)
978				}
979				found := false
980				for _, e := range p.Trail {
981					if e.Op == "发运" && e.Shipment == no {
982						found = true
983						break
984					}
985				}
986				if !found {
987					return fmt.Errorf("%w: 运输单 %q 的成员包裹 %q 缺少对应的发运轨迹", ErrCorrupt, no, pid)
988				}
989			}
990			received := receivedByShipment[no]
991			receivedCount := 0
992			for _, pid := range sh.Parcels {
993				if received[pid] {
994					receivedCount++
995				}
996			}
997			if sh.ReceivedBy != "" {
998				r, ok := l.Receives[sh.ReceivedBy]
999				if !ok || r == nil || r.Shipment != no {
1000					return fmt.Errorf("%w: 运输单 %q 标记的接收请求号 %q 无法对应", ErrCorrupt, no, sh.ReceivedBy)
1001				}
1002				if receivedCount != len(sh.Parcels) {
1003					return fmt.Errorf("%w: 运输单 %q 标记已全部接收（接收请求号 %q），但按接收事实仍有成员未接收",
1004						ErrCorrupt, no, sh.ReceivedBy)
1005				}
1006			} else if receivedCount == len(sh.Parcels) {
1007				return fmt.Errorf("%w: 运输单 %q 的全部成员均已接收，但缺少全部接收标记", ErrCorrupt, no)
1008			}
1009			// 改址链：按保存顺序（不按时间）核对，每次改址的前目的站必须等于当时的
1010			// 有效目的站，新目的站不同于当时有效目的站与源站；关联缺失或矛盾即损坏。
1011			eff := sh.To
1012			seenReroute := make(map[string]bool, len(sh.Reroutes))
1013			for i, req := range sh.Reroutes {
1014				r, ok := l.Reroutes[req]
1015				if !ok || r == nil {
1016					return fmt.Errorf("%w: 运输单 %q 的第 %d 次改址引用了不存在的改址请求 %q", ErrCorrupt, no, i+1, req)
1017				}
1018				if seenReroute[req] {
1019					return fmt.Errorf("%w: 运输单 %q 的改址列表中改址请求 %q 重复", ErrCorrupt, no, req)
1020				}
1021				seenReroute[req] = true
1022				if r.Shipment != no {
1023					return fmt.Errorf("%w: 改址请求 %q 属于运输单 %q，却列入运输单 %q 的改址列表", ErrCorrupt, req, r.Shipment, no)
1024				}
1025				if r.From != eff {
1026					return fmt.Errorf("%w: 运输单 %q 的第 %d 次改址（请求 %q）前目的站 %q 与当时有效目的站 %q 不符，改址链断裂",
1027						ErrCorrupt, no, i+1, req, r.From, eff)
1028				}
1029				eff = r.To
1030			}
1031			for _, pid := range sh.Parcels {
1032				if received[pid] {
1033					continue // 已收件的现状不限：后续交接、冻结、配送或再次发运不妨碍余件接收
1034				}
1035				p := l.Parcels[pid]
1036				inTransitCount[pid]++
1037				if p.Status != statusInTransit || p.Station != sh.From {
1038					return fmt.Errorf("%w: 运输单 %q 的成员包裹 %q 尚未接收，但当前归属 %q、状态 %q，不在该单在途",
1039						ErrCorrupt, no, pid, p.Station, p.Status)
1040				}
1041			}
1042		}
1043		for id, p := range l.Parcels {
1044			if p.Status == statusInTransit && inTransitCount[id] != 1 {
1045				return fmt.Errorf("%w: 包裹 %q 当前为站间在途，但未接收运输单数为 %d，应恰好属于一张运输单的未接收成员",
1046					ErrCorrupt, id, inTransitCount[id])
1047			}
1048		}
1049		// 接收：接收站点必须等于受理时的有效目的站（原目的站应用该件此前各次改址后，
1050		// 由逐件轨迹校验核对），成员必须非空、不重复、均属原单且按发运保存顺序排列；
1051		// 同一运输单各次接收的成员不得重叠（同单同件只能接收一次）；每件成员的轨迹中
1052		// 都有与该接收请求一致的接收记录。关联缺失、同单同件重复接收或与轨迹矛盾即损坏。
1053		receiveSeen := make(map[string]map[string]string) // 运输单号 -> 包裹 -> 接收请求号
1054		for req, r := range l.Receives {
1055			if r == nil || req != r.Request || r.Shipment == "" || r.Station == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
1056				return fmt.Errorf("%w: 接收请求号 %q 的接收结果不完整", ErrCorrupt, req)
1057			}
1058			sh, ok := l.Shipments[r.Shipment]
1059			if !ok || sh == nil {
1060				return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的运输单 %q", ErrCorrupt, req, r.Shipment)
1061			}
1062			member := make(map[string]bool, len(sh.Parcels))
1063			for _, pid := range sh.Parcels {
1064				member[pid] = true
1065			}
1066			seen := make(map[string]bool, len(r.Parcels))
1067			pos := 0 // 成员必须按发运保存顺序排列：在 sh.Parcels 中的位置严格递增
1068			for _, pid := range r.Parcels {
1069				if !member[pid] {
1070					return fmt.Errorf("%w: 接收请求号 %q 的包裹 %q 不属于运输单 %q", ErrCorrupt, req, pid, r.Shipment)
1071				}
1072				if seen[pid] {
1073					return fmt.Errorf("%w: 接收请求号 %q 的成员 %q 重复", ErrCorrupt, req, pid)
1074				}
1075				seen[pid] = true
1076				at := -1
1077				for i := pos; i < len(sh.Parcels); i++ {
1078					if sh.Parcels[i] == pid {
1079						at = i
1080						break
1081					}
1082				}
1083				if at < 0 {
1084					return fmt.Errorf("%w: 接收请求号 %q 的成员顺序与运输单 %q 的发运保存顺序不一致", ErrCorrupt, req, r.Shipment)
1085				}
1086				pos = at + 1
1087				if prev, dup := receiveSeen[r.Shipment][pid]; dup {
1088					return fmt.Errorf("%w: 包裹 %q 在运输单 %q 下被接收请求 %q 与 %q 重复接收，同单同件只能接收一次",
1089						ErrCorrupt, pid, r.Shipment, prev, req)
1090				}
1091				if receiveSeen[r.Shipment] == nil {
1092					receiveSeen[r.Shipment] = make(map[string]string)
1093				}
1094				receiveSeen[r.Shipment][pid] = req
1095			}
1096			for _, pid := range r.Parcels {
1097				p, ok := l.Parcels[pid]
1098				if !ok {
1099					return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
1100				}
1101				found := false
1102				for _, e := range p.Trail {
1103					if e.Op == "接收" && e.Request == req {
1104						found = true
1105						break
1106					}
1107				}
1108				if !found {
1109					return fmt.Errorf("%w: 接收请求号 %q 的成员包裹 %q 缺少对应的接收轨迹", ErrCorrupt, req, pid)
1110				}
1111			}
1112		}
1113		// 改址：请求号、运输单、前后目的站、原因、集合与时间完整；新目的站不同于
1114		// 前目的站与源站；运输单的改址列表必须按保存顺序恰含该请求一次（链式衔接
1115		// 由运输单校验核对）；集合非空、不重复、均属原单且按发运保存顺序排列；
1116		// 每件成员的轨迹中都有与该改址请求一致的改址记录。关联为空、缺失或矛盾即损坏。
1117		for req, r := range l.Reroutes {
1118			if r == nil || req != r.Request || r.Shipment == "" || r.From == "" || r.To == "" ||
1119				r.From == r.To || r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
1120				return fmt.Errorf("%w: 改址请求号 %q 的改址结果不完整", ErrCorrupt, req)
1121			}
1122			sh, ok := l.Shipments[r.Shipment]
1123			if !ok || sh == nil {
1124				return fmt.Errorf("%w: 改址请求号 %q 引用了不存在的运输单 %q", ErrCorrupt, req, r.Shipment)
1125			}
1126			if r.To == sh.From {
1127				return fmt.Errorf("%w: 改址请求号 %q 的新目的站 %q 与运输单 %q 源站相同", ErrCorrupt, req, r.To, r.Shipment)
1128			}
1129			linked := 0
1130			for _, q := range sh.Reroutes {
1131				if q == req {
1132					linked++
1133				}
1134			}
1135			if linked != 1 {
1136				return fmt.Errorf("%w: 改址请求号 %q 与运输单 %q 的改址列表关联缺失或重复（出现 %d 次）", ErrCorrupt, req, r.Shipment, linked)
1137			}
1138			member := make(map[string]bool, len(sh.Parcels))
1139			for _, pid := range sh.Parcels {
1140				member[pid] = true
1141			}
1142			seen := make(map[string]bool, len(r.Parcels))
1143			pos := 0 // 集合必须按发运保存顺序排列：在 sh.Parcels 中的位置严格递增
1144			for _, pid := range r.Parcels {
1145				if !member[pid] {
1146					return fmt.Errorf("%w: 改址请求号 %q 的包裹 %q 不属于运输单 %q", ErrCorrupt, req, pid, r.Shipment)
1147				}
1148				if seen[pid] {
1149					return fmt.Errorf("%w: 改址请求号 %q 的集合中包裹 %q 重复", ErrCorrupt, req, pid)
1150				}
1151				seen[pid] = true
1152				at := -1
1153				for i := pos; i < len(sh.Parcels); i++ {
1154					if sh.Parcels[i] == pid {
1155						at = i
1156						break
1157					}
1158				}
1159				if at < 0 {
1160					return fmt.Errorf("%w: 改址请求号 %q 的集合顺序与运输单 %q 的发运保存顺序不一致", ErrCorrupt, req, r.Shipment)
1161				}
1162				pos = at + 1
1163			}
1164			for _, pid := range r.Parcels {
1165				p, ok := l.Parcels[pid]
1166				if !ok {
1167					return fmt.Errorf("%w: 改址请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
1168				}
1169				found := false
1170				for _, e := range p.Trail {
1171					if e.Op == "改址" && e.Request == req {
1172						found = true
1173						break
1174					}
1175				}
1176				if !found {
1177					return fmt.Errorf("%w: 改址请求号 %q 的成员包裹 %q 缺少对应的改址轨迹", ErrCorrupt, req, pid)
1178				}
1179			}
1180		}
1181		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
1182		// 再核对两张结果表与包裹当前状态的对应关系。
1183		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
1184		for id, p := range l.Parcels {
1185			var open string
1186			for i, e := range p.Trail {
1187				switch e.Op {
1188				case "冻结":
1189					if open != "" {
1190						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
1191							ErrCorrupt, id, i+1, open)
1192					}
1193					open = e.Incident
1194				case "解除冻结":
1195					if open != e.Incident {
1196						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
1197							ErrCorrupt, id, i+1, e.Incident, open)
1198					}
1199					open = ""
1200				}
1201			}
1202			if p.Status == statusFrozen && open == "" {
1203				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
1204			}
1205			if p.Status != statusFrozen && open != "" {
1206				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
1207			}
1208			if open != "" {
1209				openIncident[id] = open
1210			}
1211		}
1212		for no, f := range l.Freezes {
1213			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
1214				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
1215			}
1216			p, ok := l.Parcels[f.Parcel]
1217			if !ok {
1218				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
1219			}
1220			if f.ReleasedBy == "" && p.Station != f.Station {
1221				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
1222					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
1223			}
1224			if f.ReleasedBy != "" {
1225				u, ok := l.Unfreezes[f.ReleasedBy]
1226				if !ok || u == nil || u.Incident != no || u.Parcel != f.Parcel {
1227					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
1228				}
1229			}
1230		}
1231		activeByParcel := make(map[string]string)
1232		for req, u := range l.Unfreezes {
1233			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
1234				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
1235			}
1236			f, ok := l.Freezes[u.Incident]
1237			if !ok || f == nil {
1238				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
1239			}
1240			if f.Parcel != u.Parcel {
1241				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
1242			}
1243			if f.ReleasedBy != req {
1244				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
1245			}
1246		}
1247		for no, f := range l.Freezes {
1248			if f.ReleasedBy != "" {
1249				continue
1250			}
1251			if other, dup := activeByParcel[f.Parcel]; dup {
1252				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
1253			}
1254			activeByParcel[f.Parcel] = no
1255			if openIncident[f.Parcel] != no {
1256				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
1257					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
1258			}
1259			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
1260				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
1261			}
1262		}
1263		return nil
1264	}
