1266	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
1267	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
1268	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
1269	func coordinationPath(path string) (string, error) {
1270		abs, err := filepath.Abs(path)
1271		if err != nil {
1272			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
1273		}
1274		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
1275			abs = resolved
1276		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
1277			abs = filepath.Join(dir, filepath.Base(abs))
1278		}
1279		return abs + ".lock", nil
1280	}
