1316	// Register 执行单件收件登记并将结果整体落盘。
1317	func (s *Store) Register(id, station string, now time.Time) (*Parcel, error) {
1318		if _, ok := s.data.Parcels[id]; ok {
1319			return nil, fmt.Errorf("包裹编号 %q 已登记，不能重复登记", id)
1320		}
1321		p := &Parcel{
1322			ID:         id,
1323			Station:    station,
1324			Status:     statusInStation,
1325			Registered: now,
1326			Trail: []Event{{
1327				Op:      "收件",
1328				Station: station,
1329				Time:    now,
1330			}},
1331		}
1332		s.data.Parcels[id] = p
1333		if err := s.save(); err != nil {
1334			delete(s.data.Parcels, id) // 落盘失败：回滚内存变更，保留原有有效数据
1335			return nil, err
1336		}
1337		return p, nil
1338	}
