1340	// Query 返回一件包裹的当前归属、状态和完整轨迹；不存在时返回 ErrNotFound。
1341	func (s *Store) Query(id string) (*Parcel, error) {
1342		p, ok := s.data.Parcels[id]
1343		if !ok {
1344			return nil, fmt.Errorf("%w: %q", ErrNotFound, id)
1345		}
1346		return p, nil
1347	}
