1349	// ActiveFreeze 返回一件包裹当前未解除异常单的冻结结果；包裹不存在或当前未冻结时返回 nil。
1350	func (s *Store) ActiveFreeze(id string) *FreezeResult {
1351		p, ok := s.data.Parcels[id]
1352		if !ok {
1353			return nil
1354		}
1355		if no := activeFreeze(p); no != "" {
1356			return s.data.Freezes[no]
1357		}
1358		return nil
1359	}
