1361	// Handoff 提交一次多件包裹的站点交接。
1362	//
1363	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
1364	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
1365	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
1366	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
1367	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
1368		if saved, ok := s.data.Handoffs[request]; ok {
1369			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
1370				return saved, true, nil
1371			}
1372			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
1373		}
1374	
1375		// 首次提交：先做全部校验，任何一件不满足都整体失败。
1376		for _, id := range parcels {
1377			p, ok := s.data.Parcels[id]
1378			if !ok {
1379				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
1380			}
1381			if p.Station != from {
1382				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
1383			}
1384			if inc := activeFreeze(p); inc != "" {
1385				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
1386			}
1387			if p.Status != statusInStation {
1388				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
1389			}
1390		}
1391	
1392		res := &HandoffResult{
1393			Request: request,
1394			From:    from,
1395			To:      to,
1396			Parcels: append([]string(nil), parcels...),
1397			Time:    now,
1398		}
1399		s.data.Handoffs[request] = res
1400	
1401		// 记录旧值，落盘失败时整体回滚。
1402		prev := make(map[string]struct {
1403			station string
1404			trail   []Event
1405		}, len(parcels))
1406		for _, id := range parcels {
1407			p := s.data.Parcels[id]
1408			prev[id] = struct {
1409				station string
1410				trail   []Event
1411			}{p.Station, append([]Event(nil), p.Trail...)}
1412			p.Station = to
1413			p.Status = statusInStation
1414			p.Trail = append(p.Trail, Event{
1415				Op:      "交接",
1416				Station: to,
1417				Request: request,
1418				Time:    now,
1419			})
1420		}
1421	
1422		if err := s.save(); err != nil {
1423			delete(s.data.Handoffs, request)
1424			for id, old := range prev {
1425				p := s.data.Parcels[id]
1426				p.Station = old.station
1427				p.Trail = old.trail
1428			}
1429			return nil, false, err
1430		}
1431		return res, false, nil
1432	}
1433	
1434	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
1435	//
1436	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
1437	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
1438	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
1439	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
1440	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
1441	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
1442	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
1443	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
1444		if saved, ok := s.data.Returns[request]; ok {
1445			if saved.Handoff == handoffReq && saved.Reason == reason {
1446				return saved, true, nil
1447			}
1448			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
1449				request, saved.Handoff, saved.Reason)
1450		}
1451	
1452		h, ok := s.data.Handoffs[handoffReq]
1453		if !ok {
1454			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
1455		}
1456		if h.ReturnedBy != "" {
1457			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
1458		}
1459	
1460		// 先做全部校验，任何一件不满足都整批拒绝。
1461		for _, id := range h.Parcels {
1462			p, ok := s.data.Parcels[id]
1463			if !ok {
1464				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
1465			}
1466			if inc := activeFreeze(p); inc != "" {
1467				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
1468			}
1469			if p.Station != h.To || p.Status != statusInStation {
1470				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
1471					id, p.Station, p.Status, h.To)
1472			}
1473			last := lastFlowEvent(p.Trail)
1474			if last.Op != "交接" || last.Request != handoffReq {
1475				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
1476					id, handoffReq)
1477			}
1478		}
1479	
1480		res := &ReturnResult{
1481			Request: request,
1482			Handoff: handoffReq,
1483			From:    h.To,
1484			To:      h.From,
1485			Reason:  reason,
1486			Parcels: append([]string(nil), h.Parcels...),
1487			Time:    now,
1488		}
1489		s.data.Returns[request] = res
1490		h.ReturnedBy = request
1491	
1492		// 记录旧值，落盘失败时整体回滚。
1493		prev := make(map[string]struct {
1494			station string
1495			trail   []Event
1496		}, len(h.Parcels))
1497		for _, id := range h.Parcels {
1498			p := s.data.Parcels[id]
1499			prev[id] = struct {
1500				station string
1501				trail   []Event
1502			}{p.Station, append([]Event(nil), p.Trail...)}
1503			p.Station = h.From
1504			p.Status = statusInStation
1505			p.Trail = append(p.Trail, Event{
1506				Op:         "退回",
1507				Station:    h.From,
1508				From:       h.To,
1509				Request:    request,
1510				RefRequest: handoffReq,
1511				Reason:     reason,
1512				Time:       now,
1513			})
1514		}
1515	
1516		if err := s.save(); err != nil {
1517			delete(s.data.Returns, request)
1518			h.ReturnedBy = ""
1519			for id, old := range prev {
1520				p := s.data.Parcels[id]
1521				p.Station = old.station
1522				p.Trail = old.trail
1523			}
1524			return nil, false, err
1525		}
1526		return res, false, nil
1527	}
1528	
1529	// Dispatch 提交一次配送批次出站。
1530	//
1531	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1532	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1533	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1534	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1535	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1536	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1537		if saved, ok := s.data.Batches[batch]; ok {
1538			if saved.RelayedFrom != "" {
1539				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1540					batch, saved.RelayRequest, saved.RelayedFrom)
1541			}
1542			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1543				return saved, true, nil
1544			}
1545			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1546		}
1547	
1548		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1549		for _, id := range parcels {
1550			p, ok := s.data.Parcels[id]
1551			if !ok {
1552				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1553			}
1554			if p.Station != station {
1555				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1556			}
1557			if inc := activeFreeze(p); inc != "" {
1558				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1559			}
1560			if p.Status != statusInStation {
1561				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1562			}
1563		}
1564	
1565		res := &BatchResult{
1566			Batch:    batch,
1567			Station:  station,
1568			Courier:  courier,
1569			Parcels:  append([]string(nil), parcels...),
1570			Time:     now,
1571			Receipts: map[string]*ReceiptEntry{},
1572		}
1573		s.data.Batches[batch] = res
1574	
1575		// 记录旧值，落盘失败时整体回滚。
1576		prev := make(map[string]struct {
1577			status string
1578			trail  []Event
1579		}, len(parcels))
1580		for _, id := range parcels {
1581			p := s.data.Parcels[id]
1582			prev[id] = struct {
1583				status string
1584				trail  []Event
1585			}{p.Status, append([]Event(nil), p.Trail...)}
1586			p.Status = statusDelivering // 站点不变，仍记出发站
1587			p.Trail = append(p.Trail, Event{
1588				Op:      "出站",
1589				Station: station,
1590				Batch:   batch,
1591				Courier: courier,
1592				Time:    now,
1593			})
1594		}
1595	
1596		if err := s.save(); err != nil {
1597			delete(s.data.Batches, batch)
1598			for id, old := range prev {
1599				p := s.data.Parcels[id]
1600				p.Status = old.status
1601				p.Trail = old.trail
1602			}
1603			return nil, false, err
1604		}
1605		return res, false, nil
1606	}
1607	
1608	// Receipt 提交一件包裹在某个配送批次下的回执。
1609	//
1610	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1611	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1612	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1613	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1614	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1615	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1616	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1617	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1618	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1619	// 失败的首次回执不占用请求号。
1620	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1621		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1622		if err != nil || replayed {
1623			return res, replayed, err
1624		}
1625		if err := s.save(); err != nil {
1626			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1627			return nil, false, err
1628		}
1629		return res, false, nil
1630	}
1631	
1632	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1633	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1634	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1635	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1636		if saved, ok := s.data.Receipts[request]; ok {
1637			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1638				return saved, true, nil, nil
1639			}
1640			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1641				request, saved.Batch, saved.Parcel, saved.Result)
1642		}
1643	
1644		b, ok := s.data.Batches[batch]
1645		if !ok {
1646			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1647		}
1648		member := false
1649		for _, id := range b.Parcels {
1650			if id == parcel {
1651				member = true
1652				break
1653			}
1654		}
1655		if !member {
1656			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1657		}
1658		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1659			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1660		}
1661		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1662		if p.Status != statusDelivering || currentBatch(p) != batch {
1663			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1664		}
1665	
1666		res = &ReceiptResult{
1667			Request: request,
1668			Batch:   batch,
1669			Parcel:  parcel,
1670			Result:  result,
1671			Reason:  reason,
1672			Time:    now,
1673		}
1674		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1675	
1676		// 记录旧值，undo 在整体落盘失败时回滚。
1677		oldStatus, oldStation := p.Status, p.Station
1678		oldTrailLen := len(p.Trail)
1679		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1680	
1681		if result == resultSigned {
1682			p.Status = statusSigned // 站点保留不变
1683		} else {
1684			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1685			p.Station = b.Station
1686		}
1687		p.Trail = append(p.Trail, Event{
1688			Op:      "回执",
1689			Station: p.Station,
1690			Batch:   batch,
1691			Result:  result,
1692			Reason:  reason,
1693			Request: request,
1694			Time:    now,
1695		})
1696		b.Receipts[parcel] = entry

