1969	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1970	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1971	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1972	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1973		if saved, ok := s.data.Unfreezes[request]; ok {
1974			if saved.Incident == incident && saved.Note == note {
1975				return saved, true, nil
1976			}
1977			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1978				request, saved.Incident, saved.Note)
1979		}
1980	
1981		f, ok := s.data.Freezes[incident]
1982		if !ok {
1983			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1984		}
1985		if f.ReleasedBy != "" {
1986			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1987		}
1988		p, ok := s.data.Parcels[f.Parcel]
1989		if !ok {
1990			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1991		}
1992		if p.Status != statusFrozen || activeFreeze(p) != incident {
1993			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1994				incident, f.Parcel, activeFreeze(p))
1995		}
1996	
1997		res = &UnfreezeResult{
1998			Request:  request,
1999			Incident: incident,
2000			Parcel:   f.Parcel,
2001			Note:     note,
2002			Time:     now,
2003		}
2004		s.data.Unfreezes[request] = res
2005		f.ReleasedBy = request
2006	
2007		// 记录旧值，落盘失败时整体回滚。
2008		oldStatus := p.Status
2009		oldTrail := append([]Event(nil), p.Trail...)
2010		p.Status = statusInStation // 在原站恢复在站，站点不变
2011		p.Trail = append(p.Trail, Event{
2012			Op:       "解除冻结",
2013			Station:  f.Station,
2014			Incident: incident,
2015			Request:  request,
2016			Note:     note,
2017			Time:     now,
2018		})
2019	
2020		if err := s.save(); err != nil {
2021			delete(s.data.Unfreezes, request)
2022			f.ReleasedBy = ""
2023			p.Status, p.Trail = oldStatus, oldTrail
2024			return nil, false, err
2025		}
2026		return res, false, nil
2027	}
