2029	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
2030	// 成员与站点取自原批次结果，不允许另选成员或站点。
2031	//
2032	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
2033	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员
2034	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
2035	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），
2036	// 各追加一条含批次、中止请求号、原因、站点和时间的收回记录；收回不是失败回执，
2037	// 批次回执记录不变。中止永久关闭原批次，原成员顺序、配送员与出站时间保留不变。
2038	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
2039	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
2040	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
2041	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
2042	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
2043	// 每批只能成功中止一次：换请求号再中止或中止已正常完成的批次均拒绝；
2044	// 失败的首次中止不占用请求号。
2045	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
2046		if saved, ok := s.data.Aborts[request]; ok {
2047			if saved.Batch == batch && saved.Reason == reason {
2048				return saved, true, nil
2049			}
2050			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
2051				request, saved.Batch, saved.Reason)
2052		}
2053	
2054		b, ok := s.data.Batches[batch]
2055		if !ok {
2056			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
2057		}
2058		if b.AbortedBy != "" {
2059			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
2060		}
2061		if b.TransferredBy != "" {
2062			return nil, false, fmt.Errorf("中止失败：批次 %q 已转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
2063		}
2064		if b.Done() {
2065			return nil, false, fmt.Errorf("中止失败：批次 %q 已全部回执完成，不能中止", batch)
2066		}
2067	
2068		// 按原成员顺序挑出全部未回执成员（批次未完成，必至少有一件）。
2069		recalled := make([]string, 0, len(b.Parcels)-len(b.Receipts))
2070		for _, pid := range b.Parcels {
2071			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
2072				recalled = append(recalled, pid)
2073			}
2074		}
2075		if len(recalled) == 0 {
2076			return nil, false, fmt.Errorf("中止失败：批次 %q 没有未回执成员，不能中止", batch)
2077		}
2078	
2079		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
2080		for _, pid := range recalled {
2081			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2082			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
2083				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
2084					pid, p.Station, p.Status, batch, b.Station)
2085			}
2086		}
2087	
2088		res = &AbortResult{
2089			Request: request,
2090			Batch:   batch,
2091			Station: b.Station,
2092			Reason:  reason,
2093			Parcels: recalled,
2094			Time:    now,
2095		}
2096		s.data.Aborts[request] = res
2097		b.AbortedBy = request
2098	
2099		// 记录旧值，落盘失败时整体回滚。
2100		prev := make(map[string]struct {
2101			status string
2102			trail  []Event
2103		}, len(recalled))
2104		for _, pid := range recalled {
2105			p := s.data.Parcels[pid]
2106			prev[pid] = struct {
2107				status string
2108				trail  []Event
2109			}{p.Status, append([]Event(nil), p.Trail...)}
2110			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
2111			p.Trail = append(p.Trail, Event{
2112				Op:      "收回",
2113				Station: b.Station,
2114				Batch:   batch,
2115				Request: request,
2116				Reason:  reason,
2117				Time:    now,
2118			})
2119		}
2120	
2121		if err := s.save(); err != nil {
2122			delete(s.data.Aborts, request)
2123			b.AbortedBy = ""
2124			for pid, old := range prev {
2125				p := s.data.Parcels[pid]
2126				p.Status = old.status
2127				p.Trail = old.trail
2128			}
2129			return nil, false, err
2130		}
2131		return res, false, nil
2132	}
