2134	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
2135	func (s *Store) BatchAbort(batch string) *AbortResult {
2136		b, ok := s.data.Batches[batch]
2137		if !ok || b.AbortedBy == "" {
2138			return nil
2139		}
2140		return s.data.Aborts[b.AbortedBy]
2141	}
