2143	// Transfer 把原批次全部尚未回执的包裹在配送途中整批交给另一配送员：
2144	// 新建批次继续配送，无需回站。成员与站点取自原批次，不允许另选成员或站点。
2145	//
2146	// 首次续接：原批次必须存在、仍开放（未中止、未转交）且有未回执成员；新批次号
2147	// 必须从未被出站或续接使用；新配送员必须与原配送员不同。未回执成员必须全部仍在
2148	// 原批次配送中且归属出发站，任一不符整批拒绝、不作任何改动。已回执成员不检查也
2149	// 不变更，其后续流转或冻结不阻止续接。全部满足时新批次按原成员顺序接纳全部未
2150	// 回执件，沿用出发站，记录新配送员及接手时间；包裹保持“配送中”及原站点，当前
2151	// 配送归属切换到新批次，各追加一条含请求号、前后批次、新配送员、站点、原因和
2152	// 时间的续接记录。原批次永久关闭为“已转交”，原成员、配送员、出站时间与真实
2153	// 回执保留不变；转交不算回执、收回或再次出站。续接算新的流转，续接后不能退回
2154	// 配送前的旧交接。
2155	// 续接请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且原批次、
2156	// 新批次、新配送员、清理后的原因相同，直接返回首次转交集合、续接信息及时间，
2157	// replayed 为 true，不检查现状、不重算成员、不改写台账；请求号相同但内容不同报
2158	// 冲突；失败的首次续接不占用请求号。
2159	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, now time.Time) (res *TransferResult, replayed bool, err error) {
2160		if saved, ok := s.data.Transfers[request]; ok {
2161			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier && saved.Reason == reason {
2162				return saved, true, nil
2163			}
2164			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
2165				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
2166		}
2167	
2168		b, ok := s.data.Batches[fromBatch]
2169		if !ok {
2170			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
2171		}
2172		if b.AbortedBy != "" {
2173			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
2174		}
2175		if b.TransferredBy != "" {
2176			return nil, false, fmt.Errorf("续接失败：批次 %q 已转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
2177		}
2178		if _, used := s.data.Batches[toBatch]; used {
2179			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
2180		}
2181		if courier == b.Courier {
2182			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
2183		}
2184	
2185		// 按原成员顺序挑出全部未回执成员（批次仍开放，必至少有一件）。
2186		moved := make([]string, 0, len(b.Parcels)-len(b.Receipts))
2187		for _, pid := range b.Parcels {
2188			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
2189				moved = append(moved, pid)
2190			}
2191		}
2192		if len(moved) == 0 {
2193			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
2194		}
2195	
2196		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
2197		for _, pid := range moved {
2198			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2199			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
2200				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
2201					pid, p.Station, p.Status, fromBatch, b.Station)
2202			}
2203		}
2204	
2205		res = &TransferResult{
2206			Request:     request,
2207			FromBatch:   fromBatch,
2208			ToBatch:     toBatch,
2209			Station:     b.Station,
2210			FromCourier: b.Courier,
2211			ToCourier:   courier,
2212			Reason:      reason,
2213			Parcels:     append([]string(nil), moved...),
2214			Time:        now,
2215		}
2216		s.data.Transfers[request] = res
2217		s.data.Batches[toBatch] = &BatchResult{
2218			Batch:        toBatch,
2219			Station:      b.Station,
2220			Courier:      courier,
2221			Parcels:      append([]string(nil), moved...),
2222			Time:         now,
2223			Receipts:     map[string]*ReceiptEntry{},
2224			RelayedFrom:  fromBatch,
2225			RelayRequest: request,
2226		}
2227		b.TransferredBy = request
2228	
2229		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
2230		prev := make(map[string][]Event, len(moved))
2231		for _, pid := range moved {
2232			p := s.data.Parcels[pid]
2233			prev[pid] = append([]Event(nil), p.Trail...)
2234			p.Trail = append(p.Trail, Event{
2235				Op:        "续接",
2236				Station:   b.Station,
2237				Batch:     toBatch,
2238				FromBatch: fromBatch,
2239				Courier:   courier,
2240				Request:   request,
2241				Reason:    reason,
2242				Time:      now,
2243			})
2244		}
2245	
2246		if err := s.save(); err != nil {
2247			delete(s.data.Transfers, request)
2248			delete(s.data.Batches, toBatch)
2249			b.TransferredBy = ""
2250			for pid, old := range prev {
2251				s.data.Parcels[pid].Trail = old
2252			}
2253			return nil, false, err
2254		}
2255		return res, false, nil
2256	}
