2272	// Ship 提交一次站间发运：整单包裹离开源站、尚未到达目的站。
2273	//
2274	// 首次发运：每件包裹必须已登记、当前归属源站且状态为在站；任一不满足则整单拒绝，
2275	// 不作任何改动（在途、配送中、已签收或已冻结的包裹均不满足）。全部满足时整单转为
2276	// “站间在途”（归属站点暂记源站），每件追加一条含运输单号、两站和时间的发运记录；
2277	// 成员按首次提交顺序保存，保存后不可修改。每件包裹同时最多属于一张未接收运输单。
2278	// 发运算新的流转：发运后不能退回此前的旧交接；运输单不是交接，不能作为退回的原交接。
2279	// 运输单号独立于已有各类编号，接收后也不释放：相同运输单号且源站、目的站、包裹集合
2280	// 相同（集合顺序无关），直接返回首次成员顺序与发运时间，replayed 为 true，不检查现状、
2281	// 不追加轨迹、不改写台账；运输单号相同但内容不同报冲突；失败的首次发运不占用运输单号。
2282	func (s *Store) Ship(shipment, from, to string, parcels []string, now time.Time) (res *ShipmentResult, replayed bool, err error) {
2283		if saved, ok := s.data.Shipments[shipment]; ok {
2284			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
2285				return saved, true, nil
2286			}
2287			return nil, false, fmt.Errorf("运输单号 %q 已用于一次不同的发运（源站=%q 目的站=%q），内容冲突", shipment, saved.From, saved.To)
2288		}
2289	
2290		// 首次发运：先做全部校验，任何一件不满足都整单拒绝。
2291		for _, id := range parcels {
2292			p, ok := s.data.Parcels[id]
2293			if !ok {
2294				return nil, false, fmt.Errorf("发运失败：包裹 %q 未登记，整单发运未执行", id)
2295			}
2296			if p.Station != from {
2297				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前归属 %q，不在源站 %q，整单发运未执行", id, p.Station, from)
2298			}
2299			if p.Status != statusInStation {
2300				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前状态为 %q，不是在站，整单发运未执行", id, p.Status)
2301			}
2302		}
2303	
2304		res = &ShipmentResult{
2305			Shipment: shipment,
2306			From:     from,
2307			To:       to,
2308			Parcels:  append([]string(nil), parcels...),
2309			Time:     now,
2310		}
2311		s.data.Shipments[shipment] = res
2312	
2313		// 记录旧值，落盘失败时整体回滚。
2314		prev := make(map[string]struct {
2315			status string
2316			trail  []Event
2317		}, len(parcels))
2318		for _, id := range parcels {
2319			p := s.data.Parcels[id]
2320			prev[id] = struct {
2321				status string
2322				trail  []Event
2323			}{p.Status, append([]Event(nil), p.Trail...)}
2324			p.Status = statusInTransit // 归属站点暂记源站，整单转为站间在途
2325			p.Trail = append(p.Trail, Event{
2326				Op:       "发运",
2327				Station:  from,
2328				From:     from,
2329				To:       to,
2330				Shipment: shipment,
2331				Time:     now,
2332			})
2333		}
2334	
2335		if err := s.save(); err != nil {
2336			delete(s.data.Shipments, shipment)
2337			for id, old := range prev {
2338				p := s.data.Parcels[id]
2339				p.Status = old.status
2340				p.Trail = old.trail
2341			}
