2486	// Reroute 提交一次运输途中改址：将一张运输单当前全部未收件改送另一目的站，
2487	// 不另建运输单、不重新发运。成员取自受理时的全部未收件，不允许另选。
2488	//
2489	// 首次受理：运输单必须存在且仍有未收件；预期当前目的站必须等于当前有效目的站
2490	// （原目的站应用已有各次改址后）；新目的站必须不同于当前有效目的站和源站。
2491	// 本次集合为受理时的全部未收件，每件都必须仍归该单在源站站间在途，任一不符
2492	// 整次拒绝、不作任何改动。已收件不参与受理条件检查也不变更，其后续合法作业
2493	// 不阻止改址。成功时按原发运顺序保存本次集合，成员仍归源站、保持站间在途及
2494	// 作业限制，只变更余件的有效目的站，逐件追加一条含请求号、运输单、前后目的站、
2495	// 原因和时间的改址轨迹；原成员、发运结果、已有接收事实与轨迹永久保留。
2496	// 改址可发生在发运与接收之间，允许再次改址（每次以当时余件为准），全部接收后
2497	// 拒绝新改址；改址不算到站、不恢复旧交接退回资格。
2498	// 改址请求号独立去重，可与运输单号及其他业务编号同名：相同请求号且运输单、
2499	// 预期当前目的站、新目的站、清理后的原因相同，直接返回首次改址信息、集合与
2500	// 时间，replayed 为 true，不检查现状、不重算余件、不改写台账（再次改址、接收
2501	// 和后续流转后仍成立）；请求号相同但内容不同报冲突；失败的首次改址不占用请求号。
2502	func (s *Store) Reroute(request, shipment, expect, to, reason string, now time.Time) (res *RerouteResult, replayed bool, err error) {
2503		if saved, ok := s.data.Reroutes[request]; ok {
2504			if saved.Shipment == shipment && saved.From == expect && saved.To == to && saved.Reason == reason {
2505				return saved, true, nil
2506			}
2507			return nil, false, fmt.Errorf("改址请求号 %q 已用于一次不同的改址（运输单=%q 新目的站=%q），内容冲突",
2508				request, saved.Shipment, saved.To)
2509		}
2510	
2511		sh, ok := s.data.Shipments[shipment]
2512		if !ok {
2513			return nil, false, fmt.Errorf("改址失败：运输单号 %q 不存在", shipment)
2514		}
2515		cur := s.effectiveTo(sh)
2516		if expect != cur {
2517			return nil, false, fmt.Errorf("改址失败：预期当前目的站 %q 与运输单 %q 当前有效目的站 %q 不符，整次改址未执行",
2518				expect, shipment, cur)
2519		}
2520		if to == cur {
2521			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与当前有效目的站相同，整次改址未执行", to)
2522		}
2523		if to == sh.From {
2524			return nil, false, fmt.Errorf("改址失败：新目的站 %q 不能与运输单 %q 源站相同，整次改址未执行", to, shipment)
2525		}
2526	
2527		// 本次集合为受理时的全部未收件，按发运保存顺序。
2528		received := s.receivedUnder(shipment)
2529		members := make([]string, 0, len(sh.Parcels))
2530		for _, pid := range sh.Parcels {
2531			if !received[pid] {
2532				members = append(members, pid)
2533			}
2534		}
2535		if len(members) == 0 {
2536			return nil, false, fmt.Errorf("改址失败：运输单 %q 已全部接收（接收请求号 %q），没有未收件，不能改址", shipment, sh.ReceivedBy)
2537		}
2538	
2539		// 先做全部校验：每件未收件都必须仍归该单在源站站间在途，任一不符整次拒绝。
2540		for _, pid := range members {
2541			p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2542			if p.Status != statusInTransit || p.Station != sh.From {
2543				return nil, false, fmt.Errorf("改址失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，整次改址未执行",
2544					pid, p.Station, p.Status, shipment, sh.From)
2545			}
2546		}
