1	package main
2	
3	import (
4		"errors"
5		"os"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	func mustTransfer(t *testing.T, s *Store, request, fromBatch, toBatch, courier, reason string, now time.Time) *TransferResult {
12		t.Helper()
13		res, replayed, err := s.Transfer(request, fromBatch, toBatch, courier, reason, now)
14		if err != nil || replayed {
15			t.Fatalf("Transfer(%q) 意外失败: %v replayed=%v", request, err, replayed)
16		}
17		return res
18	}
19	
20	func mustReceiptOK(t *testing.T, s *Store, request, batch, parcel, result, reason string, now time.Time) {
21		t.Helper()
22		if _, _, err := s.Receipt(request, batch, parcel, result, reason, now); err != nil {
23			t.Fatalf("Receipt(%q) 意外失败: %v", request, err)
24		}
25	}
26	
27	// 准备一个在站点A 出发、张三配送的批次 B1（P001、P002、P003），P001 已签收。
28	func setupRelayBase(t *testing.T, s *Store) {
29		t.Helper()
30		t1 := tClock(2026, 10, 5, 9, 0)
31		mustRegister(t, s, "P001", "站点A", t1)
32		mustRegister(t, s, "P002", "站点A", t1)
33		mustRegister(t, s, "P003", "站点A", t1)
34		mustDispatch(t, s, "B1", "站点A", "张三", []string{"P001", "P002", "P003"}, tClock(2026, 10, 5, 9, 30))
35		mustReceiptOK(t, s, "RC1", "B1", "P001", resultSigned, "", tClock(2026, 10, 5, 10, 0))
36	}
37	
38	func TestTransferSuccess(t *testing.T) {
39		s, _ := openTempStore(t)
40		setupRelayBase(t, s)
41	
42		t2 := tClock(2026, 10, 5, 11, 0)
43		res := mustTransfer(t, s, "T1", "B1", "B2", "李四", "原配送员车辆故障", t2)
44		if res.Request != "T1" || res.FromBatch != "B1" || res.ToBatch != "B2" ||
45			res.Station != "站点A" || res.FromCourier != "张三" || res.ToCourier != "李四" ||
46			res.Reason != "原配送员车辆故障" || !res.Time.Equal(t2) {
47			t.Fatalf("续接结果不符: %+v", res)
48		}
49		if len(res.Parcels) != 2 || res.Parcels[0] != "P002" || res.Parcels[1] != "P003" {
50			t.Fatalf("转交集合应为未回执成员、按原成员顺序: %v", res.Parcels)
51		}
52	
53		// 转交件保持配送中及原站点，当前配送归属切换到新批次，各追加续接轨迹。
54		for _, pid := range []string{"P002", "P003"} {
55			p, _ := s.Query(pid)
56			if p.Station != "站点A" || p.Status != statusDelivering {
57				t.Fatalf("续接后 %s 应保持配送中、站点不变: %+v", pid, p)
58			}
59			if currentBatch(p) != "B2" {
60				t.Fatalf("%s 当前配送归属应切换到 B2", pid)
61			}
62			if len(p.Trail) != 3 {
63				t.Fatalf("%s 应有三条轨迹，得到 %d", pid, len(p.Trail))
64			}
65			e := p.Trail[2]
66			if e.Op != "续接" || e.Station != "站点A" || e.FromBatch != "B1" || e.Batch != "B2" ||
67				e.Courier != "李四" || e.Request != "T1" || e.Reason != "原配送员车辆故障" || !e.Time.Equal(t2) {
68				t.Fatalf("%s 续接轨迹不符: %+v", pid, e)
69			}
70		}
71	
72		// 已回执成员不动。
73		p1, _ := s.Query("P001")
74		if p1.Status != statusSigned || len(p1.Trail) != 3 || p1.Trail[2].Op != "回执" {
75			t.Fatalf("已回执成员不得被改变: %+v", p1)
76		}
77	
78		// 原批次永久关闭为已转交，原成员、配送员、出站时间与真实回执保留。
79		old, _ := s.BatchQuery("B1")
80		if old.TransferredBy != "T1" || old.Courier != "张三" || len(old.Parcels) != 3 ||
81			len(old.Receipts) != 1 || old.Receipts["P001"].Request != "RC1" {
82			t.Fatalf("原批次应标记转交且保留原信息: %+v", old)
83		}
84	
85		// 新批次按原顺序接纳全部未回执件，沿用出发站，记录新配送员及接手时间。
86		nb, _ := s.BatchQuery("B2")
87		if nb.Station != "站点A" || nb.Courier != "李四" || !nb.Time.Equal(t2) ||
88			nb.RelayedFrom != "B1" || nb.RelayRequest != "T1" ||
89			len(nb.Parcels) != 2 || nb.Parcels[0] != "P002" || nb.Parcels[1] != "P003" {
90			t.Fatalf("新批次不符: %+v", nb)
91		}
92		if s.BatchTransferSource("B1") != res || s.TransferOf("T1") != res {
93			t.Fatal("BatchTransferSource/TransferOf 应返回续接结果")
94		}
95		if s.BatchTransferSource("B2") != nil || s.TransferOf("NOPE") != nil {
96			t.Fatal("未转交批次或不存在的请求号应无续接结果")
97		}
98	}
99	
100	func TestTransferReplayAndConflict(t *testing.T) {
101		s, _ := openTempStore(t)
102		setupRelayBase(t, s)
103		t2 := tClock(2026, 10, 5, 11, 0)
104		first := mustTransfer(t, s, "T1", "B1", "B2", "李四", "车辆故障", t2)
105	
106		// 续接后新批次继续流转：回执一件、再次续接。
107		mustReceiptOK(t, s, "RC2", "B2", "P002", resultSigned, "", tClock(2026, 10, 5, 12, 0))
108		mustTransfer(t, s, "T2", "B2", "B3", "王五", "再次转交", tClock(2026, 10, 5, 13, 0))
109	
110		// 同号同内容重放：返回首次集合、续接信息及时间，不检查现状、不重算成员、不改写台账。
111		before, _ := os.ReadFile(s.path)
112		got, replayed, err := s.Transfer("T1", "B1", "B2", "李四", "车辆故障", tClock(2026, 10, 5, 14, 0))
