### pending computation helper

```go
// transfersOutOf 返回批次各次转出的续接结果，按提交顺序（批次不存在或未转出时为空）。
func (s *Store) transfersOutOf(b *BatchResult) []*TransferResult {
    out := make([]*TransferResult, 0, len(b.Relays))
    for _, req := range b.Relays {
        if t := s.data.Transfers[req]; t != nil { out = append(out, t) }
    }
    return out
}

// transferredSet 返回批次已转交出的包裹集合（包裹 -> 续接请求号）。
func (s *Store) transferredSet(b *BatchResult) map[string]string {
    out := map[string]string{}
    for _, t := range s.transfersOutOf(b) {
        for _, pid := range t.Parcels { out[pid] = t.Request }
    }
    return out
}

// pendingParcels 返回批次当前待配送成员：无有效回执且未转交，按原成员顺序。
func (s *Store) pendingParcels(b *BatchResult) []string {
    transferred := s.transferredSet(b)
    out := []string{}
    for _, pid := range b.Parcels {
        if transferred[pid] != "" { continue }
        if e, done := b.Receipts[pid]; done && e.RevokedBy == "" { continue }
        out = append(out, pid)
    }
    return out
}
```

